// Animated Angkor Wat Background GIF + Strip (480x270, 6 frames)
anim("bg_angkor", { w: 480, h: 270, frames: 6, fps: 6 }, (c) => {
  c.stamp("_angkor_base", 0, 0)
  // Animated birds gliding across sunrise sky
  const bx = (80 + c.frame * 14) % 460
  const flap = c.frame % 2 === 0 ? -1 : 1
  c.px(bx, 64 + flap, "S"); c.px(bx + 1, 64, "S"); c.px(bx + 2, 64 + flap, "S")
  c.px(bx + 18, 72 - flap, "S"); c.px(bx + 19, 72, "S"); c.px(bx + 20, 72 - flap, "S")
  // Water shimmer lines across bottom reflection pool (y: 215..265)
  for (let i = 0; i < 16; i++) {
    const wy = 216 + ((i * 7) % 46)
    const wx = ((i * 53 + c.frame * 11) % 440) + 10
    c.hline(wx, wy, 10 + (i % 8), i % 2 === 0 ? "w" : "u")
  }
})

// Animated Bayon Twilight Background GIF + Strip (480x270, 6 frames)
anim("bg_bayon", { w: 480, h: 270, frames: 6, fps: 6 }, (c) => {
  c.stamp("_bayon_base", 0, 0)
  // Twinkling stars
  const stars = [[42, 24], [120, 38], [210, 18], [310, 32], [415, 22], [170, 52], [360, 44]]
  for (let i = 0; i < stars.length; i++) {
    if ((c.frame + i) % 3 === 0) {
      const [sx, sy] = stars[i]
      c.px(sx, sy, "w"); c.px(sx - 1, sy, "H"); c.px(sx + 1, sy, "H"); c.px(sx, sy - 1, "H"); c.px(sx, sy + 1, "H")
    }
  }
  // Flickering temple torch sparks & glowing fireflies
  const fireflies = [[70, 195], [160, 185], [295, 190], [315, 212], [418, 210], [240, 165]]
  for (let i = 0; i < fireflies.length; i++) {
    const [fx, fy] = fireflies[i]
    const dy = (c.frame + i) % 2 === 0 ? -1 : 1
    c.rect(fx, fy + dy, 2, 2, (c.frame + i) % 3 === 0 ? "w" : "Y")
  }
})

// Royal Khmer Dino (64x52) — Run (6 frames), Jump (2 frames), Duck (64x36, 4 frames)
anim("dino_run", { w: 64, h: 52, frames: 6, fps: 10 }, (c) => {
  const bob = [0, -2, -3, -1, -2, -3][c.frame]
  c.stamp("_dino_ref", 0, bob)
})
anim("dino_jump", { w: 64, h: 52, frames: 2, fps: 4 }, (c) => {
  c.stamp("_dino_ref", 0, c.frame === 0 ? -3 : 0)
})
anim("dino_duck", { w: 64, h: 38, frames: 4, fps: 10 }, (c) => {
  const bob = [0, 1, 0, -1][c.frame]
  c.stamp("_dino_ref", 0, -14 + bob)
})

// Golden Khmer Singha (64x52) — Run (6 frames), Jump (2 frames), Duck (64x38, 4 frames)
anim("singha_run", { w: 64, h: 52, frames: 6, fps: 10 }, (c) => {
  const bob = [0, -2, -3, -1, -2, -3][c.frame]
  c.stamp("_singha_ref", 0, bob)
})
anim("singha_jump", { w: 64, h: 52, frames: 2, fps: 4 }, (c) => {
  c.stamp("_singha_ref", 0, c.frame === 0 ? -3 : 0)
})
anim("singha_duck", { w: 64, h: 38, frames: 4, fps: 10 }, (c) => {
  const bob = [0, 1, 0, -1][c.frame]
  c.stamp("_singha_ref", 0, -14 + bob)
})
